"use client";

import React, { useEffect, useRef, useState } from "react";
import { useImageUpload } from "@/hooks/useImageUpload";
import { UploadOverlay } from "./UploadOverlay";

export const CustomShapesSection = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [w, setW] = useState(1000);
  const [h, setH] = useState(1000);
  const [r, setR] = useState(250);
  const [color, setColor] = useState("#072942");
  const [diagonalStrategy, setDiagonalStrategy] = useState<"primary" | "secondary">("primary");

  const [uploadedImage, setUploadedImage] = useState<HTMLImageElement | null>(null);
  const [originalFilename, setOriginalFilename] = useState<string>("image");
  const [scale, setScale] = useState(1.0);
  const [offsetX, setOffsetX] = useState(0);
  const [offsetY, setOffsetY] = useState(0);
  const [imageOpacity, setImageOpacity] = useState(1.0);
  const [flipH, setFlipH] = useState(false);
  const [flipV, setFlipV] = useState(false);
  const [imageRotation, setImageRotation] = useState(0);

  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [showUploadOverlay, setShowUploadOverlay] = useState(false);
  const hasDragged = useRef(false);

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset this tool? All unsaved work will be lost.")) {
      setUploadedImage(null);
      setOriginalFilename("image");
      setScale(1.0);
      setOffsetX(0);
      setOffsetY(0);
      setImageOpacity(1.0);
      setFlipH(false);
      setFlipV(false);
      setImageRotation(0);
      setW(1000);
      setH(1000);
      setR(20);
      setColor("#43E098");
      setDiagonalStrategy("primary");
      setShowUploadOverlay(false);
    }
  };

  const renderCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.clearRect(0, 0, w, h);
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";
    ctx.fillStyle = color;

    const drawPath = () => {
      const safeR = Math.min(r, Math.min(w, h) / 2);
      ctx.beginPath();
      if (diagonalStrategy === "secondary") {
        ctx.moveTo(0, 0);
        ctx.arcTo(w, 0, w, h, safeR);
        ctx.lineTo(w, h);
        ctx.arcTo(0, h, 0, 0, safeR);
      } else {
        ctx.moveTo(safeR, 0);
        ctx.lineTo(w, 0);
        ctx.lineTo(w, h - safeR);
        ctx.arcTo(w, h, w - safeR, h, safeR);
        ctx.lineTo(0, h);
        ctx.lineTo(0, safeR);
        ctx.arcTo(0, 0, safeR, 0, safeR);
      }
      ctx.closePath();
    };

    drawPath();
    ctx.fill();

    if (uploadedImage) {
      ctx.save();
      drawPath();
      ctx.clip();
      ctx.translate(w / 2 + offsetX, h / 2 + offsetY);
      ctx.rotate((imageRotation * Math.PI) / 180);
      ctx.scale(flipH ? -scale : scale, flipV ? -scale : scale);
      ctx.globalAlpha = imageOpacity;
      ctx.drawImage(uploadedImage, -uploadedImage.width / 2, -uploadedImage.height / 2);
      ctx.restore();
    }
  };

  useEffect(() => {
    renderCanvas();
  }, [uploadedImage, scale, offsetX, offsetY, imageOpacity, flipH, flipV, imageRotation, w, h, r, color, diagonalStrategy]);

  const onUploadSuccess = (img: HTMLImageElement, filename: string) => {
    setOriginalFilename(filename);
    setUploadedImage(img);
    setScale(Math.max(w / img.width, h / img.height));
    setOffsetX(0);
    setOffsetY(0);
    setImageRotation(0);
  };

  const { handleImageUpload, processFile } = useImageUpload(onUploadSuccess);

  const handleMouseDown = (e: React.MouseEvent) => {
    hasDragged.current = false;
    if (!uploadedImage || !canvasRef.current) return;
    setIsDragging(true);
    const rect = canvasRef.current.getBoundingClientRect();
    setDragStart({
      x: e.clientX * (w / rect.width) - offsetX,
      y: e.clientY * (h / rect.height) - offsetY,
    });
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (!isDragging || !canvasRef.current) return;
    hasDragged.current = true;
    const rect = canvasRef.current.getBoundingClientRect();
    setOffsetX(e.clientX * (w / rect.width) - dragStart.x);
    setOffsetY(e.clientY * (h / rect.height) - dragStart.y);
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleContainerClick = () => {
    if (!hasDragged.current) {
      setShowUploadOverlay(true);
    }
  };

  useEffect(() => {
    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("mouseup", handleMouseUp);
    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleMouseUp);
    };
  }, [isDragging, dragStart, w, h]);

  const handleWheel = (e: React.WheelEvent) => {
    if (!uploadedImage) return;
    let newScale = scale * (e.deltaY < 0 ? 1.04 : 0.96);
    newScale = Math.max(0.05, Math.min(newScale, 15));
    setScale(newScale);
  };

  const exportImage = () => {
    if (!canvasRef.current) return;
    const link = document.createElement("a");
    const safeName = originalFilename.split(".")[0] || "image";
    link.download = `${safeName}_custom_shape.png`;
    link.href = canvasRef.current.toDataURL("image/png", 1.0);
    link.click();
  };

  const handleRot = (deg: number) => {
    setImageRotation(((deg % 360) + 360) % 360);
  };

  const setBrandColor = (c: string) => setColor(c);

  return (
    <div className="ws">
      <div 
        className="stage"
        ref={containerRef}
        onMouseDown={handleMouseDown}
        onWheel={handleWheel}
        onClick={handleContainerClick}
        style={{ position: 'relative' }}
      >
        <UploadOverlay 
          show={showUploadOverlay || !uploadedImage} 
          onUpload={handleImageUpload} 
          onDropFile={processFile}
          onClose={() => setShowUploadOverlay(false)} 
        />
        <canvas ref={canvasRef} width={w} height={h}></canvas>
        <div className="hint" style={{ position: 'absolute', bottom: '20px', left: '50%', transform: 'translateX(-50%)', background: 'var(--card)', padding: '8px 16px', borderRadius: '20px', border: '1px solid var(--line)' }}>
          💡 Drag to reposition · Scroll to zoom
        </div>
      </div>

      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3>Custom Shapes</h3>
          <button className="chip" onClick={handleReset}>Reset</button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div>
            <div className="lb">Corner Strategy</div>
            <div className="two">
              <button
                className="pb"
                style={diagonalStrategy === "primary" ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}}
                onClick={() => setDiagonalStrategy("primary")}
              >
                ◤ TL + BR ◢
              </button>
              <button
                className="pb"
                style={diagonalStrategy === "secondary" ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}}
                onClick={() => setDiagonalStrategy("secondary")}
              >
                ◥ TR + BL ◣
              </button>
            </div>
          </div>

          <div className="two">
            <div>
              <div className="lb">Width <b>{w}px</b></div>
              <input
                type="range"
                min="300"
                max="2000"
                step="1"
                value={w}
                onChange={(e) => setW(parseInt(e.target.value))}
                style={{ width: '100%', accentColor: 'var(--brand)' }}
              />
            </div>
            <div>
              <div className="lb">Height <b>{h}px</b></div>
              <input
                type="range"
                min="300"
                max="2000"
                step="1"
                value={h}
                onChange={(e) => setH(parseInt(e.target.value))}
                style={{ width: '100%', accentColor: 'var(--brand)' }}
              />
            </div>
          </div>

          <div>
            <div className="lb">Radius <b>{r}px</b></div>
            <input
              type="range"
              min="0"
              max="500"
              step="1"
              value={r}
              onChange={(e) => setR(parseInt(e.target.value))}
              style={{ width: '100%', accentColor: 'var(--brand)' }}
            />
          </div>

          <div>
            <div className="lb">Transformations</div>
            <div className="two">
              <button
                className="pb"
                style={flipH ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}}
                onClick={() => setFlipH(!flipH)}
              >
                ↔ Flip H
              </button>
              <button
                className="pb"
                style={flipV ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}}
                onClick={() => setFlipV(!flipV)}
              >
                ↕ Flip V
              </button>
            </div>
          </div>

          <div>
            <div className="lb">Zoom <b>{scale.toFixed(2)}x</b></div>
            <input
              type="range"
              min="0.1"
              max="5"
              step="0.01"
              value={scale}
              onChange={(e) => setScale(parseFloat(e.target.value))}
              disabled={!uploadedImage}
              style={{ width: '100%', accentColor: 'var(--brand)' }}
            />
          </div>

          <div className="two">
            <div>
              <div className="lb">X <b>{Math.round(offsetX)}px</b></div>
              <input
                type="range"
                min="-1500"
                max="1500"
                step="1"
                value={offsetX}
                onChange={(e) => setOffsetX(parseInt(e.target.value))}
                disabled={!uploadedImage}
                style={{ width: '100%', accentColor: 'var(--brand)' }}
              />
            </div>
            <div>
              <div className="lb">Y <b>{Math.round(offsetY)}px</b></div>
              <input
                type="range"
                min="-1500"
                max="1500"
                step="1"
                value={offsetY}
                onChange={(e) => setOffsetY(parseInt(e.target.value))}
                disabled={!uploadedImage}
                style={{ width: '100%', accentColor: 'var(--brand)' }}
              />
            </div>
          </div>

          <div>
            <div className="lb">Rotate Image <b>{imageRotation}°</b></div>
            <div className="two" style={{ marginBottom: '10px' }}>
              <button className="pb" onClick={() => handleRot(imageRotation - 90)}>↺ 90°</button>
              <button className="pb" onClick={() => handleRot(imageRotation + 90)}>↻ 90°</button>
            </div>
            <input
              type="range"
              min="0"
              max="360"
              step="1"
              value={imageRotation}
              onChange={(e) => setImageRotation(parseInt(e.target.value))}
              disabled={!uploadedImage}
              style={{ width: '100%', accentColor: 'var(--brand)' }}
            />
          </div>

          <div>
            <div className="lb">Base Color</div>
            <input
              type="color"
              value={color}
              onChange={(e) => setColor(e.target.value)}
              style={{ width: "100%", height: "40px", cursor: 'pointer', border: '1px solid var(--line)', borderRadius: '8px', padding: 0, marginBottom: '10px' }}
            />
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '8px' }}>
              {["#2DBFF9", "#072942", "#43E098", "#F95C15", "#9D4EDD", "#286070", "#FFFFFF"].map((c) => (
                <div
                  key={c}
                  style={{ background: c, height: '24px', borderRadius: '4px', cursor: 'pointer', border: '1px solid var(--line)' }}
                  onClick={() => setBrandColor(c)}
                ></div>
              ))}
            </div>
          </div>

          <div>
            <div className="lb">Import Image</div>
            <div style={{ position: 'relative' }}>
              <div className="pb" style={{ textAlign: 'center', cursor: 'pointer' }}>Choose Source File...</div>
              <input type="file" accept="image/*" onChange={handleImageUpload} style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer' }} />
            </div>
          </div>

          <div>
            <div className="lb">Mask Opacity <b>{Math.round(imageOpacity * 100)}%</b></div>
            <input
              type="range"
              min="0"
              max="100"
              value={imageOpacity * 100}
              onChange={(e) => setImageOpacity(parseFloat(e.target.value) / 100)}
              style={{ width: '100%', accentColor: 'var(--brand)' }}
            />
          </div>

          <button className="dl" style={{ background: color, color: '#fff', filter: 'brightness(0.9)', border: 'none' }} onClick={exportImage}>
            Download Shape ({w}x{h})
          </button>
        </div>
      </div>
    </div>
  );
};

"use client";

import React, { useRef, useState, useEffect } from "react";
import QRCode from "qrcode";
import Peer, { DataConnection } from "peerjs";
import localforage from "localforage";

export const DataTransferSection = () => {
  const [role, setRole] = useState<"sender" | "receiver" | null>(null);

  // Sender state
  const [senderName, setSenderName] = useState("");
  const [transferName, setTransferName] = useState("");
  const [filesToSend, setFilesToSend] = useState<File[]>([]);
  const [isSendSetup, setIsSendSetup] = useState(true);
  const [transferId, setTransferId] = useState("");

  // Receiver state
  const [receiveCode, setReceiveCode] = useState("");
  const [receiveName, setReceiveName] = useState("");
  const [receiveState, setReceiveState] = useState<"setup" | "connecting" | "active" | "done">("setup");
  const [receiveProgress, setReceiveProgress] = useState(0);
  const [receiveMeta, setReceiveMeta] = useState<any>(null);

  const qrCanvasRef = useRef<HTMLCanvasElement>(null);
  const peerRef = useRef<Peer | null>(null);
  const connRef = useRef<DataConnection | null>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFilesToSend(Array.from(e.target.files));
    }
  };

  const startSendFlow = async () => {
    if (!senderName) return alert("Please enter your name.");
    if (filesToSend.length === 0) return alert("Please select files to send.");

    const tId = Math.floor(100000 + Math.random() * 900000).toString();
    setTransferId(tId);
    setRole("sender");
    setIsSendSetup(false);

    if (qrCanvasRef.current) {
      QRCode.toCanvas(qrCanvasRef.current, tId, {
        width: 100, margin: 2, color: { dark: "#000", light: "#fff" }
      });
    }

    const peer = new Peer(tId, { debug: 2 });
    peerRef.current = peer;

    peer.on("connection", (conn) => {
      connRef.current = conn;
      conn.on("data", (data: any) => {
        if (data.type === "request-meta") {
          conn.send({
            type: "meta",
            transferName: transferName || "File Transfer",
            senderName,
            files: filesToSend.map(f => ({ name: f.name, size: f.size, type: f.type }))
          });
        }
      });
    });
  };

  const startReceiveFlow = () => {
    if (!receiveCode) return alert("Please enter a transfer code.");
    setRole("receiver");
    setReceiveState("connecting");

    const peer = new Peer({ debug: 2 });
    peerRef.current = peer;

    peer.on("open", () => {
      const conn = peer.connect(receiveCode);
      connRef.current = conn;

      conn.on("open", () => {
        setReceiveState("active");
        conn.send({ type: "request-meta" });
      });

      conn.on("data", (data: any) => {
        if (data.type === "meta") {
          setReceiveMeta(data);
        }
      });
    });
  };

  const cancelTransfer = () => {
    if (peerRef.current) peerRef.current.destroy();
    setRole(null);
    setIsSendSetup(true);
    setReceiveState("setup");
    setFilesToSend([]);
    setTransferId("");
    setReceiveMeta(null);
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset this tool? All unsaved work will be lost.")) {
      cancelTransfer();
      setSenderName("");
      setTransferName("");
      setReceiveCode("");
      setReceiveName("");
      setReceiveProgress(0);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB", "TB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
  };

  const totalSize = filesToSend.reduce((acc, f) => acc + f.size, 0);

  return (
    <div className="ws">
      <div className="stage" style={{ padding: '24px', overflowY: 'auto' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
          <div>
            <h2 style={{ margin: '0 0 8px 0' }}>Data Transfer (Sender)</h2>
            <p className="dim-badge" style={{ margin: 0 }}>Transfer large files directly over WebRTC</p>
          </div>
          <button className="chip" onClick={handleReset}>Reset</button>
        </div>

        {role !== "receiver" && (
          <div style={{ background: 'var(--card)', borderRadius: '12px', padding: '24px', border: '1px solid var(--line)' }}>
            {isSendSetup ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                <div className="two">
                  <div>
                    <label className="lb">Your Name</label>
                    <input type="text" value={senderName} onChange={(e) => setSenderName(e.target.value)} placeholder="e.g. Pankaj" style={{ width: "100%", padding: "12px", background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: "8px", fontFamily: "var(--font-mono)", fontSize: "13px", outline: "none", color: 'var(--text)' }} />
                  </div>
                  <div>
                    <label className="lb">Transfer Name (Optional)</label>
                    <input type="text" value={transferName} onChange={(e) => setTransferName(e.target.value)} placeholder="e.g. Project Files" style={{ width: "100%", padding: "12px", background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: "8px", fontFamily: "var(--font-mono)", fontSize: "13px", outline: "none", color: 'var(--text)' }} />
                  </div>
                </div>

                <div className="dz-upload-zone" style={{ border: '2px dashed var(--line)', borderRadius: '12px', padding: '40px 24px', textAlign: 'center', position: "relative", background: 'var(--bg)' }}>
                  <div style={{ fontSize: '32px', marginBottom: '12px' }}>📦</div>
                  <div style={{ fontWeight: 600, marginBottom: '8px' }}>Drop file here or click to browse</div>
                  <div style={{ fontSize: '13px', color: 'var(--muted)' }}>Supports any file size up to 50GB</div>
                  <input type="file" multiple onChange={handleFileSelect} style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", opacity: 0, cursor: "pointer" }} />
                </div>

                {filesToSend.length > 0 && (
                  <div style={{ padding: "16px", borderRadius: "8px", background: 'var(--bg)', border: '1px solid var(--line)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <div style={{ fontWeight: 600, marginBottom: "4px" }}>{filesToSend.length === 1 ? filesToSend[0].name : `${filesToSend.length} files`}</div>
                      <div style={{ fontSize: "12px", color: 'var(--muted)' }}>{formatSize(totalSize)}</div>
                    </div>
                    <button className="dl" onClick={startSendFlow} style={{ background: "var(--brand)", color: '#fff', border: 'none' }}>Create Transfer</button>
                  </div>
                )}
              </div>
            ) : (
              <div style={{ display: 'flex', gap: '32px' }}>
                <div style={{ flex: 1 }}>
                  <div style={{ padding: "16px", borderRadius: "8px", background: 'var(--bg)', border: '1px solid var(--line)', marginBottom: "20px" }}>
                    <div className="lb" style={{ marginBottom: "8px" }}>Transfer Info</div>
                    <div style={{ fontWeight: 600, marginBottom: "8px", fontSize: "16px", color: "var(--brand)" }}>{transferName || "File Transfer"}</div>
                    <div style={{ fontSize: "13px", marginBottom: "8px", color: 'var(--muted)' }}>From: <span style={{ color: 'var(--text)' }}>{senderName}</span></div>
                    <div style={{ fontSize: "13px", fontFamily: "var(--font-mono)", color: 'var(--muted)' }}>{filesToSend.length} files ({formatSize(totalSize)})</div>
                  </div>

                  <div className="lb" style={{ marginBottom: "12px" }}>Receivers</div>
                  <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                    {connRef.current ? (
                      <div style={{ fontSize: "13px", color: "#43E098", background: 'rgba(67, 224, 152, 0.1)', padding: '12px', borderRadius: '8px' }}>Peer Connected! (Transfer logic simplified in migration)</div>
                    ) : (
                      <div className="checkered-bg" style={{ fontSize: "13px", textAlign: "center", padding: "20px 0", borderRadius: '8px', border: '1px solid var(--line)' }}>Waiting for connections...</div>
                    )}
                  </div>

                  <button className="pb" onClick={cancelTransfer} style={{ marginTop: "24px", color: '#ff3b30', borderColor: 'rgba(255, 59, 48, 0.5)' }}>Cancel Transfer</button>
                </div>

                <div style={{ width: '200px', textAlign: "center", background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '12px', padding: '24px' }}>
                  <div style={{ fontSize: "12px", marginBottom: "12px", color: 'var(--muted)' }}>Transfer Code</div>
                  <div style={{ fontFamily: "var(--font-mono)", fontSize: "28px", letterSpacing: "2px", fontWeight: 700, marginBottom: '20px' }}>{transferId}</div>
                  <canvas ref={qrCanvasRef} style={{ borderRadius: "8px", background: "white", padding: "8px", width: "120px", height: "120px", margin: "0 auto", display: "block" }}></canvas>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="panel" style={{ opacity: role === "sender" ? 0.5 : 1, pointerEvents: role === "sender" ? 'none' : 'auto' }}>
        <div style={{ marginBottom: '20px' }}>
          <h3>Receive File</h3>
        </div>

        {role !== "sender" && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {receiveState === "setup" && (
              <>
                <div>
                  <label className="lb">Enter Transfer Code:</label>
                  <input type="text" value={receiveCode} onChange={(e) => setReceiveCode(e.target.value)} placeholder="e.g. 123456" style={{ width: "100%", padding: "12px", background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: "8px", fontFamily: "var(--font-mono)", fontSize: "16px", letterSpacing: "2px", outline: "none", color: 'var(--text)' }} />
                </div>
                <div>
                  <label className="lb">Your Name:</label>
                  <input type="text" value={receiveName} onChange={(e) => setReceiveName(e.target.value)} placeholder="e.g. Rahul" style={{ width: "100%", padding: "12px", background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: "8px", fontFamily: "var(--font-mono)", fontSize: "14px", outline: "none", color: 'var(--text)' }} />
                </div>
                <div style={{ marginTop: 'auto', paddingTop: '20px' }}>
                  <button className="dl" onClick={startReceiveFlow} style={{ width: "100%", background: "#43E098", color: '#000', border: 'none' }}>Request Access</button>
                </div>
              </>
            )}

            {receiveState === "connecting" && (
              <div style={{ textAlign: "center", padding: "40px 20px" }}>
                <div style={{ color: "#43E098", fontWeight: 600, fontSize: '16px' }}>Connecting...</div>
                <div style={{ marginTop: "12px", fontSize: "13px", color: 'var(--muted)' }}>Waiting for sender approval...</div>
              </div>
            )}

            {receiveState === "active" && (
              <>
                <div style={{ padding: "16px", borderRadius: "8px", background: 'var(--bg)', border: '1px solid var(--line)', marginBottom: "20px" }}>
                  <div className="lb" style={{ marginBottom: "8px" }}>Incoming Transfer</div>
                  <div style={{ fontWeight: 600, marginBottom: "8px", fontSize: "16px", color: "#43E098" }}>{receiveMeta?.transferName || "File Transfer"}</div>
                  <div style={{ fontSize: "13px", marginBottom: "8px", color: 'var(--muted)' }}>From: <span style={{ color: 'var(--text)' }}>{receiveMeta?.senderName}</span></div>
                  <div style={{ fontSize: "13px", fontFamily: "var(--font-mono)", color: 'var(--muted)' }}>{receiveMeta?.files?.length} files</div>
                </div>

                <div>
                  <div style={{ height: "6px", background: "var(--line)", borderRadius: "4px", overflow: "hidden" }}>
                    <div style={{ height: "100%", width: `${receiveProgress}%`, background: "#43E098", borderRadius: "4px", transition: "width 0.2s ease" }}></div>
                  </div>
                  <div style={{ display: "flex", justifyContent: "space-between", marginTop: "12px", fontSize: "12px", fontFamily: "var(--font-mono)", color: 'var(--muted)' }}>
                    <span>Waiting for data...</span>
                    <span>{receiveProgress}%</span>
                  </div>
                </div>

                <div style={{ marginTop: 'auto', paddingTop: '20px' }}>
                  <button className="pb" onClick={cancelTransfer} style={{ width: "100%", color: '#ff3b30', borderColor: 'rgba(255, 59, 48, 0.5)' }}>Cancel Transfer</button>
                </div>
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

"use client";

import React, { useRef, useState, useEffect } from "react";
import JSZip from "jszip";

type FileObj = {
  id: string;
  file: File;
  img: HTMLImageElement;
  url: string;
  width: number;
  height: number;
};

export const FormatConverterSection = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [files, setFiles] = useState<FileObj[]>([]);
  const [outFormat, setOutFormat] = useState("image/png");
  const [outExt, setOutExt] = useState("png");

  const [quality, setQuality] = useState(92);
  const [resizeW, setResizeW] = useState<number | "">("");
  const [resizeH, setResizeH] = useState<number | "">("");
  const [lockAR, setLockAR] = useState(true);
  const [bgColor, setBgColor] = useState("#FFFFFF");

  const [isDragOver, setIsDragOver] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusChip, setStatusChip] = useState<"Ready" | "Processing..." | "Done" | "Error">("Ready");

  const handleFiles = async (fileList: FileList | File[]) => {
    let loadPromises: Promise<void>[] = [];
    const newFiles: FileObj[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const file = fileList[i];
      if (!file.type.startsWith("image/")) continue;

      const promise = new Promise<void>((resolve) => {
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => {
          newFiles.push({
            id: Date.now().toString() + Math.random().toString().slice(2, 6),
            file: file,
            img: img,
            url: url,
            width: img.width,
            height: img.height,
          });
          resolve();
        };
        img.src = url;
      });
      loadPromises.push(promise);
    }

    await Promise.all(loadPromises);

    setFiles((prev) => {
      const combined = [...prev, ...newFiles];
      if (prev.length === 0 && combined.length > 0) {
        if (!resizeW) setResizeW(combined[0].width);
        if (!resizeH) setResizeH(combined[0].height);
      }
      return combined;
    });
  };

  const removeFile = (id: string) => {
    setFiles((prev) => prev.filter((f) => f.id !== id));
  };

  const clearAll = () => {
    files.forEach((f) => URL.revokeObjectURL(f.url));
    setFiles([]);
    setResizeW("");
    setResizeH("");
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset this tool? All unsaved work will be lost.")) {
      clearAll();
      setOutFormat("image/png");
      setOutExt("png");
      setQuality(92);
      setLockAR(true);
      setBgColor("#FFFFFF");
      setIsProcessing(false);
      setProgress(0);
      setStatusChip("Ready");
    }
  };

  const handleResizeWChange = (val: string) => {
    const w = val === "" ? "" : parseInt(val);
    setResizeW(w);
    if (lockAR && files.length > 0 && typeof w === "number") {
      const aspect = files[0].height / files[0].width;
      setResizeH(Math.round(w * aspect));
    }
  };

  const handleResizeHChange = (val: string) => {
    const h = val === "" ? "" : parseInt(val);
    setResizeH(h);
    if (lockAR && files.length > 0 && typeof h === "number") {
      const aspect = files[0].width / files[0].height;
      setResizeW(Math.round(h * aspect));
    }
  };

  const processSingleFile = async (fileObj: FileObj, canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D) => {
    const targetW = typeof resizeW === "number" ? resizeW : fileObj.width;
    const targetH = typeof resizeH === "number" ? resizeH : fileObj.height;

    canvas.width = targetW;
    canvas.height = targetH;

    if (outFormat === "image/jpeg") {
      ctx.fillStyle = bgColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";
    ctx.drawImage(fileObj.img, 0, 0, targetW, targetH);

    const q = quality / 100;
    const dataUrl = canvas.toDataURL(outFormat, q);

    const res = await fetch(dataUrl);
    const blob = await res.blob();

    return { blob, dataUrl, targetW, targetH };
  };

  const convertAndDownload = async () => {
    if (files.length === 0) return;

    setStatusChip("Processing...");
    setIsProcessing(true);
    setProgress(5);

    try {
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");
      if (!ctx) throw new Error("Could not get canvas context");

      if (files.length === 1) {
        const result = await processSingleFile(files[0], canvas, ctx);
        setProgress(100);

        const safeName = files[0].file.name.split(".")[0];
        const link = document.createElement("a");
        link.download = `${safeName}_converted.${outExt}`;
        link.href = result.dataUrl;
        link.click();
      } else {
        const zip = new JSZip();
        const folder = zip.folder("batch-converted");

        for (let i = 0; i < files.length; i++) {
          const fileObj = files[i];
          const result = await processSingleFile(fileObj, canvas, ctx);
          const safeName = fileObj.file.name.split(".")[0];
          folder?.file(`${safeName}_converted.${outExt}`, result.blob);

          setProgress(5 + ((i + 1) / files.length) * 80);
        }

        setStatusChip("Processing...");
        const zipBlob = await zip.generateAsync({ type: "blob" });
        setProgress(100);

        const url = URL.createObjectURL(zipBlob);
        const link = document.createElement("a");
        link.download = `batch-converted.zip`;
        link.href = url;
        link.click();
        URL.revokeObjectURL(url);
      }

      setStatusChip("Done");
    } catch (err) {
      console.error(err);
      setStatusChip("Error");
    } finally {
      setTimeout(() => {
        setIsProcessing(false);
        setProgress(0);
        setStatusChip("Ready");
      }, 3000);
    }
  };

  return (
    <div className="ws">
      <div className="stage" style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '16px', overflowY: 'auto' }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: '1px solid var(--line)', paddingBottom: '16px' }}>
          <h3>Source Images</h3>
          <span style={{ fontSize: '12px', color: 'var(--muted)', background: 'var(--card)', border: '1px solid var(--line)', padding: '4px 8px', borderRadius: '4px' }}>
            {files.length > 0 ? `${files.length} Image(s)` : "—"}
          </span>
        </div>

        <div
          className={`dz-upload-zone ${isDragOver ? "drag-over" : ""}`}
          style={{ 
            border: `2px dashed ${isDragOver ? 'var(--brand)' : 'var(--line)'}`, 
            borderRadius: '12px', 
            padding: '40px', 
            textAlign: 'center', 
            cursor: 'pointer',
            background: isDragOver ? 'rgba(232, 104, 47, 0.05)' : 'var(--card)',
            transition: 'all 0.2s'
          }}
          onClick={() => fileInputRef.current?.click()}
          onDragEnter={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragLeave={(e) => { e.preventDefault(); setIsDragOver(false); }}
          onDrop={(e) => {
            e.preventDefault();
            setIsDragOver(false);
            if (e.dataTransfer.files.length) handleFiles(e.dataTransfer.files);
          }}
        >
          <div style={{ fontSize: '32px', marginBottom: '12px' }}>🖼</div>
          <div style={{ fontWeight: 600, marginBottom: '8px' }}>Drop image(s) or click to browse</div>
          <div style={{ fontSize: '12px', color: 'var(--muted)' }}>JPG · PNG · WEBP · GIF · BMP</div>
          <input type="file" ref={fileInputRef} accept="image/*" multiple style={{ display: "none" }} onChange={(e) => { if (e.target.files) handleFiles(e.target.files); }} />
        </div>

        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {files.length === 0 ? (
            <div style={{ padding: "40px 20px", textAlign: "center", color: "var(--muted)", fontSize: "14px" }}>No images uploaded</div>
          ) : (
            files.map((fileObj, idx) => (
              <div key={fileObj.id} style={{ display: 'flex', alignItems: 'center', gap: '12px', background: 'var(--card)', border: '1px solid var(--line)', padding: '12px', borderRadius: '8px' }}>
                <div style={{ fontSize: '12px', color: 'var(--muted)', width: '20px' }}>{idx + 1}</div>
                <img src={fileObj.url} alt={fileObj.file.name} style={{ width: '40px', height: '40px', objectFit: 'cover', borderRadius: '4px', border: '1px solid var(--line)' }} />
                <div style={{ flex: 1, overflow: 'hidden' }}>
                  <div style={{ fontWeight: 600, fontSize: '14px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{fileObj.file.name}</div>
                  <div style={{ fontSize: '11px', color: 'var(--muted)', fontFamily: 'var(--font-mono)' }}>{(fileObj.file.size / 1024).toFixed(1)} KB • {fileObj.width}×{fileObj.height}</div>
                </div>
                <button onClick={() => removeFile(fileObj.id)} style={{ background: 'transparent', border: 'none', color: 'var(--muted)', cursor: 'pointer', fontSize: '16px', padding: '4px 8px' }}>✕</button>
              </div>
            ))
          )}
        </div>
      </div>

      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3>Conversion Options</h3>
          <button className="chip" onClick={handleReset}>Reset</button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div>
            <div className="lb">Output Format</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "8px" }}>
              <button className="pb" style={outFormat === "image/jpeg" ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}} onClick={() => { setOutFormat("image/jpeg"); setOutExt("jpg"); }}>JPG</button>
              <button className="pb" style={outFormat === "image/png" ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}} onClick={() => { setOutFormat("image/png"); setOutExt("png"); }}>PNG</button>
              <button className="pb" style={outFormat === "image/webp" ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}} onClick={() => { setOutFormat("image/webp"); setOutExt("webp"); }}>WEBP</button>
            </div>
          </div>

          <div style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '12px', padding: '16px' }}>
            <div className="lb" style={{ marginBottom: '12px' }}>Quality & Compression</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
              <input type="range" min="1" max="100" value={quality} onChange={(e) => setQuality(parseInt(e.target.value))} style={{ flex: 1, accentColor: 'var(--brand)' }} />
              <div style={{ width: '40px', textAlign: 'right', fontWeight: 600, fontFamily: 'var(--font-mono)', fontSize: '14px' }}>{quality}%</div>
            </div>
            <div style={{ fontSize: "11px", color: "var(--muted)" }}>Quality affects JPG & WEBP output size. PNG is vector/lossless processes.</div>
          </div>

          <div style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '12px', padding: '16px' }}>
            <div className="lb" style={{ marginBottom: '12px' }}>Resize (optional)</div>
            <div className="two">
              <div>
                <div style={{ fontSize: '12px', marginBottom: '4px', color: 'var(--muted)' }}>Width (px)</div>
                <input type="number" placeholder="Auto" min="1" max="8000" value={resizeW} onChange={(e) => handleResizeWChange(e.target.value)} style={{ width: '100%', background: 'var(--card)', border: '1px solid var(--line)', padding: '8px', borderRadius: '6px', color: 'var(--text)' }} />
              </div>
              <div>
                <div style={{ fontSize: '12px', marginBottom: '4px', color: 'var(--muted)' }}>Height (px)</div>
                <input type="number" placeholder="Auto" min="1" max="8000" value={resizeH} onChange={(e) => handleResizeHChange(e.target.value)} style={{ width: '100%', background: 'var(--card)', border: '1px solid var(--line)', padding: '8px', borderRadius: '6px', color: 'var(--text)' }} />
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "12px" }}>
              <input type="checkbox" checked={lockAR} onChange={(e) => setLockAR(e.target.checked)} style={{ accentColor: "var(--brand)", width: "16px", height: "16px", cursor: "pointer" }} />
              <label style={{ fontSize: "12px", color: "var(--text)", cursor: "pointer" }} onClick={() => setLockAR(!lockAR)}>Lock aspect ratio</label>
            </div>
          </div>

          {outFormat === "image/jpeg" && (
            <div style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '12px', padding: '16px' }}>
              <div className="lb" style={{ marginBottom: '12px' }}>Background (for JPG)</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <input type="color" value={bgColor} onChange={(e) => setBgColor(e.target.value)} style={{ height: "36px", width: '100px', borderRadius: "6px", cursor: "pointer", padding: 0, border: '1px solid var(--line)' }} />
                <span style={{ fontSize: "12px", color: "var(--muted)" }}>Fills transparency</span>
              </div>
            </div>
          )}

          <div style={{ marginTop: "auto", paddingTop: '20px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
              <span className="lb" style={{ margin: 0 }}>Status</span>
              <span style={{ 
                fontSize: '11px', 
                padding: '4px 8px', 
                borderRadius: '4px', 
                background: statusChip === "Processing..." ? 'rgba(232, 104, 47, 0.2)' : (statusChip === "Done" ? 'rgba(16, 185, 129, 0.2)' : 'var(--bg)'),
                color: statusChip === "Processing..." ? 'var(--brand)' : (statusChip === "Done" ? '#10b981' : 'var(--muted)'),
                border: '1px solid',
                borderColor: statusChip === "Processing..." ? 'var(--brand)' : (statusChip === "Done" ? '#10b981' : 'var(--line)')
              }}>
                {statusChip}
              </span>
            </div>

            {isProcessing && (
              <div style={{ height: '4px', background: 'var(--line)', borderRadius: '2px', overflow: 'hidden', marginBottom: '16px' }}>
                <div style={{ height: '100%', background: 'var(--brand)', width: `${progress}%`, transition: 'width 0.2s' }}></div>
              </div>
            )}

            <button className="dl" disabled={files.length === 0 || isProcessing} onClick={convertAndDownload} style={{ width: '100%', background: "var(--brand)", color: '#fff', border: 'none', opacity: (files.length === 0 || isProcessing) ? 0.5 : 1 }}>
              ⬇ Convert & Download
            </button>
            <button className="pb" onClick={clearAll} style={{ width: "100%", marginTop: "8px", border: 'none', background: 'transparent', color: 'var(--muted)' }}>
              ✕ Clear All
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

"use client";

import React, { useRef, useState, useEffect } from "react";
import JSZip from "jszip";
import * as pdfjsLib from "pdfjs-dist";

// Initialize PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

type ExtractedAsset = {
  name: string;
  blob: Blob;
  url: string;
};

export const ImageExtractorSection = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [extractedAssets, setExtractedAssets] = useState<ExtractedAsset[]>([]);
  const [statusText, setStatusText] = useState("Ready");
  const [statusType, setStatusType] = useState<"idle" | "processing" | "success">("idle");
  const [originalFilename, setOriginalFilename] = useState("");
  const [isDragOver, setIsDragOver] = useState(false);
  const [format, setFormat] = useState<"png" | "jpeg">("png");

  const resetUI = () => {
    setExtractedAssets([]);
    setStatusText("Ready");
    setStatusType("idle");
    setOriginalFilename("");
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset this tool? All unsaved work will be lost.")) {
      resetUI();
      setFormat("png");
    }
  };

  const handleFile = async (file: File) => {
    resetUI();
    setStatusText("Processing...");
    setStatusType("processing");
    setOriginalFilename(file.name);

    const name = file.name.toLowerCase();
    const newAssets: ExtractedAsset[] = [];

    try {
      if (name.endsWith(".pptx")) {
        await extractZipMedia(file, "ppt/media/", newAssets);
      } else if (name.endsWith(".docx")) {
        await extractZipMedia(file, "word/media/", newAssets);
      } else if (name.endsWith(".pdf")) {
        await extractPDF(file, newAssets);
      } else {
        throw new Error("Unsupported file type");
      }

      setExtractedAssets(newAssets);
      if (newAssets.length > 0) {
        setStatusText("Extraction Complete");
        setStatusType("success");
      } else {
        setStatusText("No media found");
        setStatusType("idle");
      }
    } catch (err: any) {
      console.error(err);
      setStatusText("Error");
      setStatusType("idle");
      alert("Processing failed: " + err.message);
    }
  };

  const extractZipMedia = async (file: File, folder: string, targetArray: ExtractedAsset[]) => {
    const zip = await JSZip.loadAsync(file);
    const promises: Promise<void>[] = [];

    zip.forEach((path, entry) => {
      if (path.startsWith(folder) && /\.(png|jpg|jpeg|gif|svg|webp|bmp)$/i.test(path)) {
        promises.push(
          entry.async("blob").then((blob) => {
            const name = path.split("/").pop() || "image";
            const url = URL.createObjectURL(blob);
            targetArray.push({ name, blob, url });
          })
        );
      }
    });

    await Promise.all(promises);
  };

  const extractPDF = async (file: File, targetArray: ExtractedAsset[]) => {
    const data = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data }).promise;

    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const viewport = page.getViewport({ scale: 2 });
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");
      if (!ctx) continue;

      canvas.width = viewport.width;
      canvas.height = viewport.height;
      await page.render({ canvasContext: ctx, viewport } as any).promise;

      const blob = await new Promise<Blob | null>((resolve) => {
        canvas.toBlob(resolve, format === "png" ? "image/png" : "image/jpeg", 0.95);
      });

      if (blob) {
        const safeName = file.name.split(".")[0] || "doc";
        const name = `${safeName}_page-${i}.${format === "png" ? "png" : "jpg"}`;
        const url = URL.createObjectURL(blob);
        targetArray.push({ name, blob, url });
      }
    }
  };

  const downloadZip = async () => {
    if (extractedAssets.length === 0) return;
    setStatusText("Archiving...");
    setStatusType("processing");

    const zip = new JSZip();
    extractedAssets.forEach((asset) => zip.file(asset.name, asset.blob));

    const blob = await zip.generateAsync({ type: "blob" });
    const url = URL.createObjectURL(blob);

    const safeName = originalFilename.split(".")[0] || "document";

    const a = document.createElement("a");
    a.href = url;
    a.download = `${safeName}_extracted.zip`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);

    setStatusText("Archived Successfully");
    setStatusType("success");
  };

  return (
    <div className="ws">
      <div className="stage" style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '16px', overflowY: 'auto' }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: '1px solid var(--line)', paddingBottom: '16px' }}>
          <h3>Extracted Asset Gallery</h3>
          <span style={{ 
            fontSize: '11px', 
            padding: '4px 8px', 
            borderRadius: '4px', 
            background: statusType === "processing" ? 'rgba(232, 104, 47, 0.2)' : (statusType === "success" ? 'rgba(16, 185, 129, 0.2)' : 'var(--bg)'),
            color: statusType === "processing" ? 'var(--brand)' : (statusType === "success" ? '#10b981' : 'var(--muted)'),
            border: '1px solid',
            borderColor: statusType === "processing" ? 'var(--brand)' : (statusType === "success" ? '#10b981' : 'var(--line)')
          }}>
            {statusText}
          </span>
        </div>

        {extractedAssets.length === 0 ? (
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: 'var(--muted)', textAlign: 'center' }}>
            <div style={{ fontSize: '32px', marginBottom: '16px' }}>📦</div>
            <div>Extracted media and rendered pages will populate here.</div>
          </div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))", gap: "16px" }}>
            {extractedAssets.map((asset, idx) => (
              <div key={idx} style={{ background: 'var(--card)', border: '1px solid var(--line)', borderRadius: '8px', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
                <div style={{ height: '140px', padding: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg)' }}>
                  <img src={asset.url} alt={asset.name} style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }} />
                </div>
                <div style={{ padding: '8px', borderTop: '1px solid var(--line)' }}>
                  <div style={{ fontSize: '11px', color: 'var(--text)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', marginBottom: '8px', fontFamily: 'var(--font-mono)' }} title={asset.name}>{asset.name}</div>
                  <a href={asset.url} download={asset.name} style={{ display: 'block', textAlign: 'center', fontSize: '11px', background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '4px', padding: '4px', color: 'var(--text)', textDecoration: 'none' }}>⬇ Download</a>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3>Source Document</h3>
          <button className="chip" onClick={handleReset}>Reset</button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div
            className={`dz-upload-zone ${isDragOver ? "drag-over" : ""}`}
            style={{ 
              border: `2px dashed ${isDragOver ? 'var(--brand)' : 'var(--line)'}`, 
              borderRadius: '12px', 
              padding: '40px', 
              textAlign: 'center', 
              cursor: 'pointer',
              background: isDragOver ? 'rgba(232, 104, 47, 0.05)' : 'var(--card)',
              transition: 'all 0.2s'
            }}
            onClick={() => fileInputRef.current?.click()}
            onDragEnter={(e) => { e.preventDefault(); setIsDragOver(true); }}
            onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
            onDragLeave={(e) => { e.preventDefault(); setIsDragOver(false); }}
            onDrop={(e) => {
              e.preventDefault();
              setIsDragOver(false);
              if (e.dataTransfer.files.length) handleFile(e.dataTransfer.files[0]);
            }}
          >
            <div style={{ fontSize: '32px', marginBottom: '12px' }}>🗂</div>
            <div style={{ fontWeight: 600, marginBottom: '8px' }}>Drop PPTX, DOCX, or PDF here</div>
            <div style={{ fontSize: '12px', color: 'var(--muted)' }}>Max 50MB · Processed Locally</div>
            <input
              type="file"
              ref={fileInputRef}
              accept=".pptx,.docx,.pdf"
              style={{ display: "none" }}
              onChange={(e) => {
                if (e.target.files?.length) handleFile(e.target.files[0]);
              }}
            />
          </div>

          <div style={{ background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '12px', padding: '16px' }}>
            <div className="lb" style={{ marginBottom: '12px' }}>PDF Extraction Settings</div>
            <div>
              <div style={{ fontSize: '12px', marginBottom: '4px', color: 'var(--muted)' }}>Format</div>
              <select 
                value={format} 
                onChange={(e) => setFormat(e.target.value as any)}
                style={{ width: '100%', background: 'var(--card)', border: '1px solid var(--line)', padding: '8px', borderRadius: '6px', color: 'var(--text)' }}
              >
                <option value="png">PNG (Lossless Quality)</option>
                <option value="jpeg">JPG (Smaller Size)</option>
              </select>
            </div>
          </div>

          <div style={{ marginTop: "auto", paddingTop: '20px' }}>
            {extractedAssets.length > 0 && (
              <button className="dl" onClick={downloadZip} style={{ width: '100%', background: "var(--brand)", color: '#fff', border: 'none', marginBottom: '8px' }}>
                ⬇ Download All as ZIP
              </button>
            )}
            <button className="pb" onClick={resetUI} style={{ width: "100%", border: 'none', background: 'transparent', color: 'var(--muted)' }}>
              ✕ Clear Workspace
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

"use client";

import React, { useRef, useState, useEffect } from "react";
// @ts-expect-error No type declarations available
import gifshot from "gifshot";

export const MP4ToGIFSection = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);

  const [selectedFileUrl, setSelectedFileUrl] = useState<string | null>(null);
  const [videoDuration, setVideoDuration] = useState(0);
  const [origWidth, setOrigWidth] = useState(0);
  const [origHeight, setOrigHeight] = useState(0);
  const [aspectRatio, setAspectRatio] = useState(1);
  const [originalFilename, setOriginalFilename] = useState("");

  const [startTime, setStartTime] = useState(0);
  const [endTime, setEndTime] = useState(10);

  const [compLevel, setCompLevel] = useState("medium");
  const [resizeW, setResizeW] = useState<number | "">("");
  const [resizeH, setResizeH] = useState<number | "">("");
  const [lockAR, setLockAR] = useState(true);

  const [isDragOver, setIsDragOver] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [statusChip, setStatusChip] = useState<"Waiting" | "Ready" | "Processing..." | "Done" | "Error">("Waiting");

  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [processingStatus, setProcessingStatus] = useState("");
  const [gifOutput, setGifOutput] = useState("");

  const showError = (msg: string) => {
    setErrorMsg(msg);
    setStatusChip("Error");
    setTimeout(() => setErrorMsg(""), 4000);
  };

  const handleFile = (file: File) => {
    if (!file.type.startsWith("video/") && !file.name.toLowerCase().match(/\.(mp4|webm|ogg|mov)$/)) {
      showError("Please upload a valid video file.");
      return;
    }

    setGifOutput("");
    setIsProcessing(false);
    setProgress(0);
    setErrorMsg("");
    setStatusChip("Waiting");

    if (selectedFileUrl) URL.revokeObjectURL(selectedFileUrl);

    const url = URL.createObjectURL(file);
    setSelectedFileUrl(url);
    setOriginalFilename(file.name);
  };

  const onLoadedMetadata = () => {
    if (!videoRef.current) return;
    const duration = videoRef.current.duration;
    const w = videoRef.current.videoWidth;
    const h = videoRef.current.videoHeight;
    const ar = w / h;

    setVideoDuration(duration);
    setOrigWidth(w);
    setOrigHeight(h);
    setAspectRatio(ar);
    setResizeW(w);
    setResizeH(h);

    setStartTime(0);
    setEndTime(Math.min(duration, 10));
    setStatusChip("Ready");
  };

  const onVideoError = () => {
    showError("Video format not supported or corrupted.");
    setSelectedFileUrl(null);
  };

  const handleTimeScrub = (isStart: boolean, val: number) => {
    let start = isStart ? val : startTime;
    let end = isStart ? endTime : val;

    if (start < 0) start = 0;
    if (end > videoDuration) end = videoDuration;

    if (start >= end) {
      if (isStart) start = Math.max(0, end - 0.1);
      else end = Math.min(videoDuration, start + 0.1);
    }

    if (end - start > 10) {
      if (isStart) {
        end = start + 10;
        if (end > videoDuration) { end = videoDuration; start = end - 10; }
      } else {
        start = end - 10;
        if (start < 0) { start = 0; end = start + 10; }
      }
    }

    setStartTime(start);
    setEndTime(end);

    if (videoRef.current) {
      videoRef.current.currentTime = isStart ? start : end;
    }
  };

  const handleResizeWChange = (val: string) => {
    const w = val === "" ? "" : parseInt(val);
    setResizeW(w);
    if (lockAR && origWidth && typeof w === "number") {
      setResizeH(Math.round(w / aspectRatio));
    }
  };

  const handleResizeHChange = (val: string) => {
    const h = val === "" ? "" : parseInt(val);
    setResizeH(h);
    if (lockAR && origHeight && typeof h === "number") {
      setResizeW(Math.round(h * aspectRatio));
    }
  };

  const convertVideo = async () => {
    if (!selectedFileUrl || !videoRef.current) return;

    setStatusChip("Processing...");
    setIsProcessing(true);
    setProgress(0);
    setProcessingStatus("Initializing Engine...");

    const targetW = typeof resizeW === "number" ? resizeW : origWidth || 480;
    const targetH = typeof resizeH === "number" ? resizeH : origHeight || 480;

    let fps = 10;
    if (compLevel === "low") fps = 5;
    if (compLevel === "medium") fps = 7;
    if (compLevel === "high") fps = 10;

    const clipDuration = endTime - startTime;
    const totalFrames = Math.max(1, Math.floor(clipDuration * fps));
    const frameInterval = 1 / fps;

    const canvas = document.createElement("canvas");
    canvas.width = targetW;
    canvas.height = targetH;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });

    const images: string[] = [];
    const originalTime = videoRef.current.currentTime;

    try {
      if (videoRef.current.readyState < 2) {
        await new Promise<void>((resolve) => {
          const h = () => { videoRef.current?.removeEventListener("loadeddata", h); resolve(); };
          videoRef.current?.addEventListener("loadeddata", h);
        });
      }

      for (let i = 0; i < totalFrames; i++) {
        const time = startTime + i * frameInterval;
        videoRef.current.currentTime = time;

        await new Promise<void>((resolve) => {
          const handler = () => {
            videoRef.current?.removeEventListener("seeked", handler);
            resolve();
          };
          videoRef.current?.addEventListener("seeked", handler);
          setTimeout(resolve, 500);
        });

        if (ctx) ctx.drawImage(videoRef.current, 0, 0, targetW, targetH);
        images.push(canvas.toDataURL("image/jpeg", 0.8));

        const percent = Math.round(((i + 1) / totalFrames) * 50);
        setProgress(percent);
        setProcessingStatus(`Extracting Frames: ${percent}%`);
      }
    } catch (err) {
      showError("Failed to extract frames from video.");
      setIsProcessing(false);
      return;
    } finally {
      if (videoRef.current) videoRef.current.currentTime = originalTime;
    }

    setProcessingStatus("Generating GIF...");

    gifshot.createGIF({
      images: images,
      gifWidth: targetW,
      gifHeight: targetH,
      frameDuration: 10 / fps,
      sampleInterval: compLevel === "low" ? 5 : compLevel === "medium" ? 15 : 30,
      progressCallback: (captureProgress: number) => {
        const percent = 50 + Math.round(captureProgress * 50);
        setProgress(percent);
        setProcessingStatus(`Rendering GIF: ${percent}%`);
      }
    }, (obj: any) => {
      if (!obj.error) {
        const image = obj.image;
        setGifOutput(image);

        const base64Length = image.length - (image.indexOf(",") + 1);
        const padding = image.charAt(image.length - 2) === "=" ? 2 : image.charAt(image.length - 1) === "=" ? 1 : 0;
        const fileSize = (base64Length * 0.75 - padding) / 1024 / 1024;

        setProcessingStatus(`Done! Estimated Size: ${fileSize.toFixed(2)} MB`);
        setStatusChip("Done");
      } else {
        showError("An error occurred during GIF generation.");
      }
      setIsProcessing(false);
    });
  };

  const downloadGif = () => {
    if (!gifOutput) return;
    const a = document.createElement("a");
    a.href = gifOutput;
    a.download = `${originalFilename.split(".")[0] || "video"}.gif`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset this tool? All unsaved work will be lost.")) {
      if (selectedFileUrl) URL.revokeObjectURL(selectedFileUrl);
      setSelectedFileUrl(null);
      setOriginalFilename("");
      setCompLevel("medium");
      setResizeW("");
      setResizeH("");
      setLockAR(true);
      setErrorMsg("");
      setStatusChip("Waiting");
      setIsProcessing(false);
      setProgress(0);
      setProcessingStatus("");
      setGifOutput("");
    }
  };

  return (
    <div className="ws">
      <div className="stage" style={{ display: 'flex', flexDirection: 'column', gap: '24px', padding: '24px', overflowY: 'auto' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h2 style={{ margin: '0 0 8px 0' }}>Source Video</h2>
            <p className="dim-badge" style={{ margin: 0 }}>{selectedFileUrl ? `${(origWidth || 0)}x${(origHeight || 0)}` : "—"}</p>
          </div>
        </div>

        <div
          className={`dz-upload-zone ${isDragOver ? "drag-over" : ""}`}
          style={{
            border: '2px dashed var(--line)',
            borderRadius: '12px',
            padding: '40px 24px',
            textAlign: 'center',
            cursor: 'pointer',
            background: 'var(--card)',
            transition: 'all 0.2s ease',
            borderColor: isDragOver ? 'var(--brand)' : 'var(--line)'
          }}
          onClick={() => fileInputRef.current?.click()}
          onDragEnter={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragLeave={(e) => { e.preventDefault(); setIsDragOver(false); }}
          onDrop={(e) => {
            e.preventDefault();
            setIsDragOver(false);
            if (e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
          }}
        >
          <div style={{ fontSize: '32px', marginBottom: '12px' }}>🎬</div>
          <div style={{ fontWeight: 600, marginBottom: '8px' }}>Drop an MP4 video or click to browse</div>
          <div style={{ fontSize: '13px', color: 'var(--muted)' }}>Max 10s extraction · Local browser processing</div>
          <input type="file" ref={fileInputRef} accept="video/mp4,video/x-m4v,video/webm,video/*" style={{ display: "none" }} onChange={(e) => { if (e.target.files?.[0]) handleFile(e.target.files[0]); }} />
        </div>

        {errorMsg && (
          <div style={{ padding: '16px', background: 'rgba(255,59,48,0.1)', color: '#ff3b30', borderRadius: '8px', border: '1px solid rgba(255,59,48,0.2)', textAlign: 'center' }}>
            {errorMsg}
          </div>
        )}

        {selectedFileUrl && (
          <div style={{ borderRadius: "12px", overflow: "hidden", background: '#000', border: '1px solid var(--line)' }}>
            <video
              ref={videoRef}
              controls
              style={{ width: "100%", outline: "none", maxHeight: "400px", display: 'block' }}
              onLoadedMetadata={onLoadedMetadata}
              onError={onVideoError}
              src={selectedFileUrl}
            ></video>
          </div>
        )}
      </div>

      <div className="panel" style={{ opacity: selectedFileUrl ? 1 : 0.5, pointerEvents: selectedFileUrl ? "auto" : "none" }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3>MP4 to GIF</h3>
          <button className="chip" onClick={handleReset} style={{ pointerEvents: 'auto' }}>Reset</button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div>
            <div className="lb">✂ Trim Video Timeline (Max 10s clip)</div>
            <div className="two">
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                <label style={{ fontSize: '13px', color: 'var(--muted)' }}>Start Time (s)</label>
                <input type="number" min="0" step="0.1" value={startTime.toFixed(1)} onChange={(e) => handleTimeScrub(true, parseFloat(e.target.value))} style={{ background: 'var(--bg)', border: '1px solid var(--line)', color: 'var(--text)', padding: '8px', borderRadius: '6px' }} />
                <input type="range" min="0" step="0.1" max={videoDuration} value={startTime} onChange={(e) => handleTimeScrub(true, parseFloat(e.target.value))} style={{ width: '100%', accentColor: 'var(--brand)' }} />
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                <label style={{ fontSize: '13px', color: 'var(--muted)' }}>End Time (s)</label>
                <input type="number" min="0.1" step="0.1" value={endTime.toFixed(1)} onChange={(e) => handleTimeScrub(false, parseFloat(e.target.value))} style={{ background: 'var(--bg)', border: '1px solid var(--line)', color: 'var(--text)', padding: '8px', borderRadius: '6px' }} />
                <input type="range" min="0.1" step="0.1" max={videoDuration} value={endTime} onChange={(e) => handleTimeScrub(false, parseFloat(e.target.value))} style={{ width: '100%', accentColor: 'var(--brand)' }} />
              </div>
            </div>
          </div>

          <div>
            <div className="lb">⚙ Compression Quality</div>
            <select value={compLevel} onChange={(e) => setCompLevel(e.target.value)} style={{ width: '100%', padding: '10px 12px', background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '6px', color: 'var(--text)', outline: 'none' }}>
              <option value="low">Low Compression (High Quality)</option>
              <option value="medium">Medium Compression (Balanced)</option>
              <option value="high">High Compression (Small File)</option>
            </select>
          </div>

          <div>
            <div className="lb">↔ Dimensions (px)</div>
            <div className="two">
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                <label style={{ fontSize: '13px', color: 'var(--muted)' }}>Width</label>
                <input type="number" min="1" max="2000" value={resizeW} onChange={(e) => handleResizeWChange(e.target.value)} style={{ background: 'var(--bg)', border: '1px solid var(--line)', color: 'var(--text)', padding: '8px', borderRadius: '6px' }} />
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                <label style={{ fontSize: '13px', color: 'var(--muted)' }}>Height</label>
                <input type="number" min="1" max="2000" value={resizeH} onChange={(e) => handleResizeHChange(e.target.value)} style={{ background: 'var(--bg)', border: '1px solid var(--line)', color: 'var(--text)', padding: '8px', borderRadius: '6px' }} />
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "12px" }}>
              <input type="checkbox" checked={lockAR} onChange={(e) => setLockAR(e.target.checked)} style={{ accentColor: "var(--brand)", width: "16px", height: "16px", cursor: "pointer" }} />
              <label style={{ fontSize: "13px", color: "var(--muted)", cursor: "pointer" }} onClick={() => setLockAR(!lockAR)}>Lock aspect ratio</label>
            </div>
          </div>

          <div style={{ marginTop: 'auto', paddingTop: '20px' }}>
            {(isProcessing || progress > 0) && (
              <div style={{ marginBottom: "16px" }}>
                <div style={{ height: "6px", background: "var(--line)", borderRadius: "4px", overflow: "hidden" }}>
                  <div style={{ height: "100%", width: `${progress}%`, background: "var(--brand)", borderRadius: "4px", transition: "width 0.2s ease" }}></div>
                </div>
                <div style={{ fontSize: "11px", fontFamily: "var(--font-mono)", color: "var(--brand)", marginTop: "8px", textAlign: 'center' }}>
                  {processingStatus}
                </div>
              </div>
            )}

            {!gifOutput && (
              <button className="dl" disabled={isProcessing} onClick={convertVideo} style={{ background: "var(--brand)", color: '#fff', width: '100%', border: 'none', opacity: isProcessing ? 0.5 : 1 }}>
                ⚡ Generate GIF File
              </button>
            )}
          </div>

          {gifOutput && (
            <div style={{ borderTop: '1px solid var(--line)', paddingTop: '20px' }}>
              <div className="lb">Generated GIF Output</div>
              <div className="checkered-bg" style={{ 
                height: "auto", 
                minHeight: "180px", 
                padding: "16px", 
                display: "flex", 
                justifyContent: "center", 
                alignItems: "center",
                borderRadius: '8px',
                border: '1px solid var(--line)',
                marginBottom: '16px'
              }}>
                <img src={gifOutput} alt="Generated GIF" style={{ borderRadius: "4px", maxWidth: "100%", boxShadow: "0 8px 24px rgba(0,0,0,0.2)" }} />
              </div>
              <button className="dl" onClick={downloadGif} style={{ width: '100%', background: "#43E098", color: '#000', border: 'none', marginBottom: '12px' }}>
                ⬇ Download GIF
              </button>
              <button className="pb" onClick={() => setGifOutput("")} style={{ width: "100%", color: "var(--brand)", borderColor: "var(--brand)" }}>
                ↺ Convert Again
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

"use client";

import React, { useRef, useState, useEffect } from "react";
import Tesseract from "tesseract.js";
import Cropper from "react-cropper";
import "cropperjs/dist/cropper.css";

type OCRMode = "direct" | "crop";

export const OCRSection = () => {
  const cropperRef = useRef<HTMLImageElement>(null);

  const [mode, setMode] = useState<OCRMode>("direct");
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [extractedText, setExtractedText] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [progressLabel, setProgressLabel] = useState("Initializing...");
  const [buttonText, setButtonText] = useState("📋 Copy Extracted Text");

  const resetState = () => {
    setImageSrc(null);
    setExtractedText("");
    setIsProcessing(false);
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset this tool? All unsaved work will be lost.")) {
      resetState();
      setMode("direct");
      setProgressLabel("Initializing...");
      setButtonText("📋 Copy Extracted Text");
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    resetState();

    const reader = new FileReader();
    reader.onload = (ev) => {
      const result = ev.target?.result as string;
      setImageSrc(result);
      if (mode === "direct") {
        executeOCR(result);
      }
    };
    reader.readAsDataURL(file);
    e.target.value = "";
  };

  const executeOCR = async (src: string) => {
    setIsProcessing(true);
    setProgressLabel("Initializing Engine...");
    setExtractedText("");

    try {
      const result = await Tesseract.recognize(src, "eng", {
        logger: (m) => {
          if (m.status === "recognizing text") {
            setProgressLabel(`Extracting... (${Math.floor(m.progress * 100)}%)`);
          }
        },
      });
      setExtractedText(result.data.text.trim() || "[No text identified in image.]");
    } catch (err) {
      console.error(err);
      setExtractedText("Error during scan.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCropExtract = () => {
    const imageElement: any = cropperRef?.current;
    const cropper = imageElement?.cropper;
    if (cropper) {
      const croppedCanvas = cropper.getCroppedCanvas({
        imageSmoothingEnabled: true,
        imageSmoothingQuality: "high",
      });
      if (croppedCanvas) {
        executeOCR(croppedCanvas.toDataURL("image/png", 1.0));
      } else {
        setExtractedText("Please draw a crop selection first.");
      }
    }
  };

  const copyToClipboard = () => {
    if (!extractedText) return;
    navigator.clipboard.writeText(extractedText).then(() => {
      setButtonText("✓ Copied to Clipboard!");
      setTimeout(() => setButtonText("📋 Copy Extracted Text"), 2000);
    }).catch(() => alert("Clipboard error."));
  };

  const zoomIn = () => {
    const imageElement: any = cropperRef?.current;
    imageElement?.cropper?.zoom(0.1);
  };

  const zoomOut = () => {
    const imageElement: any = cropperRef?.current;
    imageElement?.cropper?.zoom(-0.1);
  };

  const recenter = () => {
    const imageElement: any = cropperRef?.current;
    imageElement?.cropper?.reset();
  };

  return (
    <div className="ws">
      <div className="stage checkered-bg" style={{ display: 'flex', flexDirection: 'column', padding: '24px', position: 'relative' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
          <div className="two" style={{ gap: '8px' }}>
            <button className="pb" style={mode === "direct" ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}} onClick={() => { setMode("direct"); resetState(); }}>① Direct Scan</button>
            <button className="pb" style={mode === "crop" ? { background: 'var(--brand)', color: '#fff', borderColor: 'var(--brand)' } : {}} onClick={() => { setMode("crop"); resetState(); }}>② Crop & Scan</button>
          </div>

          {mode === "crop" && imageSrc && (
            <div className="two" style={{ gap: '8px' }}>
              <button className="chip" onClick={zoomIn}>➕ Zoom In</button>
              <button className="chip" onClick={zoomOut}>➖ Zoom Out</button>
              <button className="chip" onClick={recenter}>🔄 Reset</button>
            </div>
          )}
        </div>

        <div style={{ flex: 1, position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px solid var(--line)', borderRadius: '12px', background: 'var(--bg)', overflow: 'hidden' }}>
          {!imageSrc && <div style={{ color: 'var(--muted)' }}>Awaiting Document Upload...</div>}

          {imageSrc && mode === "direct" && (
            <img src={imageSrc} alt="OCR Workspace" style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} />
          )}

          {imageSrc && mode === "crop" && (
            <div style={{ width: '100%', height: '100%' }}>
              <Cropper
                src={imageSrc}
                style={{ height: '100%', width: "100%" }}
                initialAspectRatio={NaN}
                guides={true}
                ref={cropperRef}
                viewMode={1}
                dragMode="crop"
                autoCropArea={0.8}
                background={false}
                zoomable={true}
              />
            </div>
          )}

          {isProcessing && (
            <div style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', zIndex: 10 }}>
              <div style={{ width: '40px', height: '40px', border: '3px solid var(--line)', borderTopColor: 'var(--brand)', borderRadius: '50%', animation: 'spin 1s linear infinite', marginBottom: '16px' }}></div>
              <div style={{ color: '#fff', fontWeight: 600 }}>{progressLabel}</div>
            </div>
          )}
        </div>

        <div className="hint" style={{ marginTop: '16px', textAlign: 'center' }}>
          {mode === "direct" ? "💡 Full image direct scan mode active" : "💡 Draw a selection box · scroll to zoom"}
        </div>
      </div>

      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3>Image to Text / OCR</h3>
          <button className="chip" onClick={handleReset}>Reset</button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', flex: 1 }}>

          {mode === "direct" ? (
            <div>
              <div className="lb">Upload (Full Scan)</div>
              <div style={{ position: 'relative' }}>
                <div className="pb" style={{ textAlign: 'center', cursor: 'pointer', borderStyle: 'dashed' }}>Upload Image File...</div>
                <input type="file" accept="image/*" onChange={handleImageUpload} style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer' }} />
              </div>
            </div>
          ) : (
            <div>
              <div className="lb">Upload (Crop Mode)</div>
              <div style={{ position: 'relative', marginBottom: '12px' }}>
                <div className="pb" style={{ textAlign: 'center', cursor: 'pointer', borderStyle: 'dashed' }}>Upload for Crop Selection...</div>
                <input type="file" accept="image/*" onChange={handleImageUpload} style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer' }} />
              </div>
              <button
                className="dl"
                onClick={handleCropExtract}
                disabled={!imageSrc || isProcessing}
                style={{ width: '100%', background: "var(--brand)", color: '#fff', border: 'none', opacity: (!imageSrc || isProcessing) ? 0.5 : 1 }}
              >
                🔍 Extract From Selected Area
              </button>
            </div>
          )}

          <div style={{ height: '1px', background: 'var(--line)' }}></div>

          <div style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
              <div className="lb" style={{ margin: 0 }}>Extracted Text</div>
              <span style={{ fontSize: '10px', color: 'var(--muted)', background: 'var(--bg)', padding: '4px 8px', borderRadius: '4px', border: '1px solid var(--line)' }}>
                {mode === "direct" ? "Direct Mode" : "Crop Mode"}
              </span>
            </div>

            <textarea
              value={extractedText}
              readOnly
              placeholder="Extracted text will appear here automatically..."
              style={{
                flex: 1,
                minHeight: '200px',
                width: '100%',
                background: 'var(--bg)',
                border: '1px solid var(--line)',
                borderRadius: '8px',
                padding: '12px',
                color: 'var(--text)',
                fontFamily: 'var(--font-mono)',
                fontSize: '13px',
                resize: 'none',
                marginBottom: '16px'
              }}
            ></textarea>

            <div className="two" style={{ gap: '12px' }}>
              <button
                className="dl"
                onClick={copyToClipboard}
                style={{ background: "var(--brand)", color: '#fff', border: 'none' }}
              >
                {buttonText}
              </button>
              <button
                className="pb"
                onClick={() => setExtractedText("")}
                style={{ border: 'none', background: 'transparent', color: 'var(--muted)' }}
              >
                ✕ Clear
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

"use client";

import React, { useRef, useState, useEffect } from "react";
import jsPDF from "jspdf";
import * as pdfjsLib from "pdfjs-dist";

// Initialize PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

type FileItem = {
  id: string;
  file: File;
  url: string;
};

export const PDFConverterSection = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [files, setFiles] = useState<FileItem[]>([]);
  const [quality, setQuality] = useState(80);
  const [pageSize, setPageSize] = useState("fit");
  const [orientation, setOrientation] = useState("auto");
  const [margin, setMargin] = useState(10);

  const [isProcessing, setIsProcessing] = useState(false);
  const [statusText, setStatusText] = useState("");
  const [progress, setProgress] = useState(0);

  const [isDragOver, setIsDragOver] = useState(false);
  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);

  const handleFiles = async (fileList: FileList | File[]) => {
    const validTypes = ["image/jpeg", "image/png", "image/webp", "image/jpg"];

    for (let i = 0; i < fileList.length; i++) {
      const file = fileList[i];
      if (validTypes.includes(file.type)) {
        setFiles((prev) => [
          ...prev,
          { id: Math.random().toString(), file, url: URL.createObjectURL(file) }
        ]);
      } else if (file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf")) {
        await extractPdfPages(file);
      }
    }
  };

  const extractPdfPages = async (file: File) => {
    setIsProcessing(true);
    setStatusText("Extracting PDF...");
    setProgress(5);

    try {
      const arrayBuffer = await file.arrayBuffer();
      const pdfDoc = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      const totalPages = pdfDoc.numPages;

      for (let pageNum = 1; pageNum <= totalPages; pageNum++) {
        setStatusText(`Extracting page ${pageNum} of ${totalPages}...`);
        setProgress(5 + (pageNum / totalPages) * 95);

        const page = await pdfDoc.getPage(pageNum);
        const viewport = page.getViewport({ scale: 2.0 });

        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        if (!ctx) continue;

        canvas.width = viewport.width;
        canvas.height = viewport.height;
        await page.render({ canvasContext: ctx, viewport } as any).promise;

        const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/jpeg", 0.95));
        if (blob) {
          const baseName = file.name.replace(/\.pdf$/i, "");
          const pageFile = new File([blob], `${baseName}_page${pageNum}.jpg`, { type: "image/jpeg" });

          setFiles((prev) => [
            ...prev,
            { id: Math.random().toString(), file: pageFile, url: URL.createObjectURL(pageFile) }
          ]);
        }
      }
    } catch (err) {
      console.error(err);
      alert("Failed to extract PDF pages.");
    } finally {
      setIsProcessing(false);
      setProgress(0);
      setStatusText("");
    }
  };

  const removeFile = (index: number) => {
    setFiles((prev) => {
      const newFiles = [...prev];
      newFiles.splice(index, 1);
      return newFiles;
    });
  };

  const fileToDataUrl = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (e) => resolve(e.target?.result as string);
      reader.readAsDataURL(file);
    });
  };

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.src = src;
    });
  };

  const generatePDF = async () => {
    if (files.length === 0) return;

    setIsProcessing(true);
    setStatusText("Initializing PDF Generation Engine...");
    setProgress(0);

    const sizes: Record<string, [number, number]> = {
      a4: [210, 297],
      a3: [297, 420],
      letter: [215.9, 279.4],
      legal: [215.9, 355.6],
    };

    let pdf: jsPDF | null = null;

    try {
      for (let i = 0; i < files.length; i++) {
        setStatusText(`Processing image ${i + 1} of ${files.length}...`);
        setProgress((i / files.length) * 100);

        const file = files[i].file;
        const rawImgData = await fileToDataUrl(file);
        const img = await loadImage(rawImgData);

        const cvs = document.createElement("canvas");
        cvs.width = img.width;
        cvs.height = img.height;
        const ctx = cvs.getContext("2d");
        if (!ctx) continue;

        ctx.drawImage(img, 0, 0, img.width, img.height);

        let mimeType = file.type === "image/png" ? "image/png" : "image/jpeg";
        const qualityVal = quality / 100;

        if (qualityVal < 1.0 && mimeType === "image/png") {
          mimeType = "image/jpeg";
          ctx.globalCompositeOperation = "destination-over";
          ctx.fillStyle = "#FFFFFF";
          ctx.fillRect(0, 0, img.width, img.height);
        }

        const imgData = cvs.toDataURL(mimeType, qualityVal);
        const jsPdfFormat = mimeType === "image/png" ? "PNG" : "JPEG";

        let isLandscape = false;
        let pW, pH;
        let currentFormat: any;
        let drawW, drawH, x, y;

        if (pageSize === "fit") {
          const imgW_mm = (img.width * 25.4) / 96;
          const imgH_mm = (img.height * 25.4) / 96;
          pW = imgW_mm;
          pH = imgH_mm;
          isLandscape = imgW_mm > imgH_mm;
          currentFormat = [pW, pH];
          drawW = pW;
          drawH = pH;
          x = 0;
          y = 0;
        } else {
          const pageFormat = sizes[pageSize];
          if (orientation === "auto") {
            isLandscape = img.width > img.height;
          } else if (orientation === "landscape") {
            isLandscape = true;
          }

          pW = isLandscape ? pageFormat[1] : pageFormat[0];
          pH = isLandscape ? pageFormat[0] : pageFormat[1];
          currentFormat = pageSize;

          const maxW = pW - margin * 2;
          const maxH = pH - margin * 2;

          drawW = maxW;
          drawH = (img.height * maxW) / img.width;

          if (drawH > maxH) {
            drawH = maxH;
            drawW = (img.width * maxH) / img.height;
          }

          x = margin + (maxW - drawW) / 2;
          y = margin + (maxH - drawH) / 2;
        }

        const orientStr = isLandscape ? "l" : "p";

        if (i === 0) {
          pdf = new jsPDF({ orientation: orientStr as "p" | "l", unit: "mm", format: currentFormat });
        } else {
          pdf?.addPage(currentFormat, orientStr as "p" | "l");
        }

        const compression = quality < 100 ? "FAST" : "NONE";
        pdf?.addImage(imgData, jsPdfFormat, x, y, drawW, drawH, undefined, compression);
      }

      setProgress(100);
      setStatusText("Finalizing and downloading...");

      const safeName = files[0].file.name.split(".")[0];
      const outName = `${safeName}_${files.length > 1 ? "batch-converted" : "converted"}.pdf`;
      pdf?.save(outName);

    } catch (err) {
      console.error(err);
      setStatusText("Error occurred during generation.");
    } finally {
      setTimeout(() => {
        setIsProcessing(false);
        setProgress(0);
        setStatusText("");
      }, 2000);
    }
  };

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedItemIndex(index);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOverItem = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  };

  const handleDropItem = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedItemIndex !== null && draggedItemIndex !== index) {
      const newFiles = [...files];
      const draggedFile = newFiles.splice(draggedItemIndex, 1)[0];
      newFiles.splice(index, 0, draggedFile);
      setFiles(newFiles);
    }
    setDraggedItemIndex(null);
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset this tool? All unsaved work will be lost.")) {
      files.forEach((f) => URL.revokeObjectURL(f.url));
      setFiles([]);
      setQuality(80);
      setPageSize("fit");
      setOrientation("auto");
      setMargin(10);
      setIsProcessing(false);
      setStatusText("");
      setProgress(0);
    }
  };

  return (
    <div className="ws">
      <div className="stage" style={{ display: 'flex', flexDirection: 'column', gap: '24px', padding: '24px', overflowY: 'auto' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h2 style={{ margin: '0 0 8px 0' }}>Upload Images</h2>
            <p className="dim-badge" style={{ margin: 0 }}>{files.length} files</p>
          </div>
        </div>

        <div
          className={`dz-upload-zone ${isDragOver ? "drag-over" : ""}`}
          onClick={() => fileInputRef.current?.click()}
          onDragEnter={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragLeave={(e) => { e.preventDefault(); setIsDragOver(false); }}
          onDrop={(e) => {
            e.preventDefault();
            setIsDragOver(false);
            if (e.dataTransfer.files.length) handleFiles(e.dataTransfer.files);
          }}
          style={{
            border: '2px dashed var(--line)',
            borderRadius: '12px',
            padding: '40px 24px',
            textAlign: 'center',
            cursor: 'pointer',
            background: 'var(--card)',
            transition: 'all 0.2s ease',
            borderColor: isDragOver ? 'var(--brand)' : 'var(--line)'
          }}
        >
          <div style={{ fontSize: '32px', marginBottom: '12px' }}>📄</div>
          <div style={{ fontWeight: 600, marginBottom: '8px' }}>Drop images here or click to browse</div>
          <div style={{ fontSize: '13px', color: 'var(--muted)' }}>JPG · PNG · WEBP · PDF (extracts pages)</div>
          <input
            type="file"
            ref={fileInputRef}
            accept="image/png,image/jpeg,image/jpg,image/webp,application/pdf,.pdf"
            multiple
            style={{ display: "none" }}
            onChange={(e) => { if (e.target.files) handleFiles(e.target.files); }}
          />
        </div>

        <div>
          {files.length === 0 ? (
            <div style={{ 
              textAlign: 'center', 
              padding: '40px', 
              border: '1px solid var(--line)', 
              borderRadius: '12px', 
              color: 'var(--muted)',
              background: 'var(--bg)' 
            }}>
              <div style={{ fontSize: '24px', marginBottom: '12px' }}>🖼️</div>
              <p style={{ margin: 0 }}>No images uploaded yet.<br />Files can be reordered by dragging.</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {files.map((fileObj, idx) => (
                <div
                  key={fileObj.id}
                  draggable
                  onDragStart={(e) => handleDragStart(e, idx)}
                  onDragOver={(e) => handleDragOverItem(e, idx)}
                  onDrop={(e) => handleDropItem(e, idx)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    background: 'var(--card)',
                    border: '1px solid var(--line)',
                    borderRadius: '8px',
                    cursor: 'grab'
                  }}
                >
                  <div style={{ color: 'var(--muted)', cursor: 'grab', userSelect: 'none' }}>≡</div>
                  <div style={{ width: '24px', height: '24px', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg)', borderRadius: '4px', fontSize: '12px', color: 'var(--muted)' }}>{idx + 1}</div>
                  <img src={fileObj.url} style={{ width: '48px', height: '48px', objectFit: 'cover', borderRadius: '4px', border: '1px solid var(--line)' }} alt={fileObj.file.name} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', fontWeight: 500, fontSize: '14px' }}>{fileObj.file.name}</div>
                    <div style={{ fontSize: '12px', color: 'var(--muted)', marginTop: '4px' }}>{(fileObj.file.size / 1024).toFixed(1)} KB</div>
                  </div>
                  <button onClick={() => removeFile(idx)} style={{ background: 'transparent', border: 'none', color: 'var(--muted)', cursor: 'pointer', padding: '8px', borderRadius: '4px' }}>✕</button>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3>PDF Converter</h3>
          <button className="chip" onClick={handleReset}>Reset</button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div>
            <div className="lb">⚙ PDF Options</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', background: 'var(--card)', border: '1px solid var(--line)', padding: '16px', borderRadius: '8px' }}>
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                  <label style={{ fontSize: '13px', fontWeight: 500 }}>Quality</label>
                  <span style={{ fontSize: '13px', color: 'var(--muted)', fontFamily: 'var(--font-mono)' }}>{quality}%</span>
                </div>
                <input type="range" min="10" max="100" value={quality} onChange={(e) => setQuality(parseInt(e.target.value))} style={{ width: '100%', accentColor: 'var(--brand)' }} />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '13px', fontWeight: 500, marginBottom: '8px' }}>Page Size</label>
                <select value={pageSize} onChange={(e) => setPageSize(e.target.value)} style={{ width: '100%', padding: '8px 12px', background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '6px', color: 'var(--text)', outline: 'none' }}>
                  <option value="fit">Fit (Same page size as image)</option>
                  <option value="a4">A4 (210 × 297 mm)</option>
                  <option value="a3">A3 (297 × 420 mm)</option>
                  <option value="letter">Letter (8.5 × 11 in)</option>
                  <option value="legal">Legal (8.5 × 14 in)</option>
                </select>
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '13px', fontWeight: 500, marginBottom: '8px' }}>Orientation</label>
                <select value={orientation} onChange={(e) => setOrientation(e.target.value)} style={{ width: '100%', padding: '8px 12px', background: 'var(--bg)', border: '1px solid var(--line)', borderRadius: '6px', color: 'var(--text)', outline: 'none' }}>
                  <option value="auto">Auto (per image)</option>
                  <option value="portrait">Always Portrait</option>
                  <option value="landscape">Always Landscape</option>
                </select>
              </div>

              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                  <label style={{ fontSize: '13px', fontWeight: 500 }}>Margin</label>
                  <span style={{ fontSize: '13px', color: 'var(--muted)', fontFamily: 'var(--font-mono)' }}>{margin}mm</span>
                </div>
                <input type="range" min="0" max="30" value={margin} onChange={(e) => setMargin(parseInt(e.target.value))} style={{ width: '100%', accentColor: 'var(--brand)' }} />
              </div>
            </div>
          </div>

          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
              <span className="lb" style={{ margin: 0 }}>Preview Sequence</span>
              <span style={{ fontSize: '11px', padding: '2px 8px', borderRadius: '12px', background: isProcessing ? 'rgba(45,191,249,0.1)' : files.length > 0 ? 'rgba(67,224,152,0.1)' : 'var(--bg)', color: isProcessing ? 'var(--brand)' : files.length > 0 ? '#43E098' : 'var(--muted)' }}>
                {isProcessing ? "Processing..." : files.length > 0 ? "Ready" : "Idle"}
              </span>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(60px, 1fr))", gap: "8px", maxHeight: "200px", overflowY: "auto", padding: "8px", border: '1px solid var(--line)', borderRadius: '8px', background: 'var(--bg)' }}>
              {files.length === 0 ? (
                <div style={{ gridColumn: "1/-1", textAlign: 'center', padding: '20px 0', color: 'var(--muted)', fontSize: '12px' }}>
                  Image thumbnails appear here
                </div>
              ) : (
                files.map((f) => (
                  <img
                    key={`preview-${f.id}`}
                    src={f.url}
                    style={{ width: "100%", height: "60px", objectFit: "cover", borderRadius: "4px", border: '1px solid var(--line)' }}
                    alt={f.file.name}
                  />
                ))
              )}
            </div>
          </div>

          <div style={{ marginTop: "auto", paddingTop: "20px" }}>
            {isProcessing && (
              <div style={{ marginBottom: "16px" }}>
                <div style={{ height: "6px", background: "var(--line)", borderRadius: "4px", overflow: "hidden" }}>
                  <div style={{ height: "100%", width: `${progress}%`, background: "var(--brand)", borderRadius: "4px", transition: "width 0.2s ease" }}></div>
                </div>
                <div style={{ fontSize: "11px", fontFamily: "var(--font-mono)", color: "var(--brand)", marginTop: "8px", textAlign: 'center' }}>
                  {statusText || `Processing... ${Math.round(progress)}%`}
                </div>
              </div>
            )}

            <button
              className="dl"
              onClick={generatePDF}
              disabled={files.length === 0 || isProcessing}
              style={{ background: "#43E098", color: '#000', width: "100%", border: 'none', opacity: (files.length === 0 || isProcessing) ? 0.5 : 1 }}
            >
              ⬇ Generate & Download PDF
            </button>
            <button
              className="pb"
              onClick={() => setFiles([])}
              style={{ width: "100%", marginTop: "12px", color: "var(--brand)", borderColor: "var(--brand)" }}
            >
              ✕ Clear All Files
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

