              <rect x="14" y="14" width="7" height="7"></rect><rect x="3" y="14" width="7" height="7"></rect>
            </svg>
            <span style={{ fontSize: '14px', fontWeight: 600 }}>Enter URL to generate QR</span>
          </div>
          <canvas ref={canvasRef} style={{ display: isGenerated ? 'block' : 'none', width: '250px', height: '250px', borderRadius: '8px', boxShadow: '0 8px 24px rgba(0,0,0,0.15)' }}></canvas>
